from collections import deque


def transform(grid):
    """Reverse the color order of concentric rectangular layers in each object."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] != 0:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            top = min(y for y, _ in cells)
            bottom = max(y for y, _ in cells)
            left = min(x for _, x in cells)
            right = max(x for _, x in cells)
            depth = (min(bottom - top + 1, right - left + 1) + 1) // 2
            layers = []
            for k in range(depth):
                color = grid[top + k][left + k]
                if color != 0 and (not layers or layers[-1] != color):
                    layers.append(color)
            if not layers:
                continue
            reverse = {color: layers[-1 - i] for i, color in enumerate(layers)}
            for y, x in cells:
                out[y][x] = reverse.get(grid[y][x], grid[y][x])
    return out
